public boolean isArmstrong(int n) {
    int original = n;
    int k = countDigits(n);
    long total = 0;
    while (n > 0) {
        int digit = n % 10;
        total += intPow(digit, k);   // exact integer power
        n /= 10;
    }
    return total == original;
}

private int countDigits(int n) {
    if (n == 0) return 1;
    int count = 0;
    while (n > 0) { count++; n /= 10; }
    return count;
}

private long intPow(int base, int exp) {
    long result = 1;
    for (int i = 0; i < exp; i++) result *= base;
    return result;
}
